<?php $pageTitle='My orders | HEX CHEATS SHOP';$activePage='orders';require __DIR__.'/_head.php'; ?>
<section class="hx-page-heading"><p class="hx-eyebrow">ORDER HISTORY</p><h1>My orders</h1><p class="hx-muted">Payment status and fulfillment updates for your purchases.</p></section><section id="ordersList" class="hx-list"><div class="hx-loading">Loading orders…</div></section>
<script>(()=>{const box=document.getElementById('ordersList'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));fetch('/api/store/orders',{credentials:'same-origin'}).then(async r=>{const d=await r.json();if(r.status===401){location.href='/login?next='+encodeURIComponent(location.pathname+location.search);return}if(!r.ok)throw Error(d.error||'Could not load orders.');const rows=d.orders||[];box.innerHTML=rows.length?rows.map(o=>`<article class="hx-panel hx-order"><div><b>${esc(o.product_name||'Product')}</b><div class="hx-muted">${esc(o.duration||'')} · ${new Date(Number(o.created_at)*1000).toLocaleString()}</div></div><span class="hx-status">${esc(o.status||'pending')}</span><b>₹${Number(o.amount||0).toFixed(2)}</b>${o.delivery_key?`<div class="hx-key">${esc(o.delivery_key)}</div>`:''}<small>Order ${esc(o.order_id||'')}</small></article>`).join(''):'<section class="hx-panel">No orders yet. <a href="/#catalog">Browse products</a></section>'}).catch(e=>box.textContent=e.message)})();</script>
